<?php get_header(); mrk_breadcrumbs(); ?><main id="content" class="shell section"><header class="archive-header"><p class="eyebrow">Knowledge hub</p><h1><?php echo is_search() ? 'Search results for: ' . esc_html(get_search_query()) : (is_home() ? 'MRK Digital Blog' : get_the_archive_title()); ?></h1></header><div class="content-layout"><div class="post-list"><?php if(have_posts()):while(have_posts()):the_post(); ?><article <?php post_class('archive-card'); ?>><p class="eyebrow"><?php echo esc_html(get_the_date()); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),35)); ?></p><a class="text-link" href="<?php the_permalink(); ?>">Read more →</a></article><?php endwhile; the_posts_pagination(); else: ?><p>No matching content was found. Try a different search or <a href="<?php echo esc_url(home_url('/contact/')); ?>">contact MRK</a>.</p><?php endif; ?></div></div></main><?php get_footer(); ?>
